#!/usr/bin/env python3
"""Compile and run the production KNX command module with host boundary stubs."""
# AI: below section was generated by an AI
import argparse
import os
from pathlib import Path
import shlex
import subprocess
import tempfile


def main():
    """Keep build output temporary; CXX may name a compiler or 'zig c++'."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--examples", action="store_true")
    parser.add_argument("--integration", action="store_true", help="Run the real WLED update/KNX packet path")
    parser.add_argument("--unit-only", action="store_true", help="Run only focused command/conversion checks")
    args = parser.parse_args()
    root = Path(__file__).resolve().parents[1]
    compiler = shlex.split(os.environ.get("CXX", "c++"), posix=os.name != "nt")
    compiler = [part.strip('"') for part in compiler]
    with tempfile.TemporaryDirectory(prefix="wled-knx-") as directory:
        exe = Path(directory) / ("knx-control.exe" if os.name == "nt" else "knx-control")
        sources = ["control_test.cpp", "integration_test.cpp"]
        if args.examples or args.unit_only:
            sources = ["control_test.cpp"]
        elif args.integration:
            sources = ["integration_test.cpp"]
        for source in sources:
            subprocess.run(compiler + ["-std=c++17", "-O2", "-Wall", "-Wextra", "-Werror",
                           "-Wno-unused-function", "-Wno-unused-parameter", "-DKNX_UM_SUPPRESS_WARN",
                           "-I", str(root / "test/knx_control/stubs"),
                           str(root / "test/knx_control" / source), "-o", str(exe)],
                           check=True, cwd=root)
            subprocess.run([str(exe)] + (["--examples"] if args.examples else []), check=True)


if __name__ == "__main__":
    main()
# AI: end
